definition.script:
var op = input.get('operation') || 'add';
var d1 = input.get('date1');
var d2 = input.get('date2') || '';
var yrs = parseInt(input.get('years') || '0');
var mos = parseInt(input.get('months') || '0');
var wks = parseInt(input.get('weeks') || '0');
var dys = parseInt(input.get('days') || '0');
var hrs = parseInt(input.get('hours') || '0');
var mins = parseInt(input.get('minutes') || '0');
var secs = parseInt(input.get('seconds') || '0');

if (!d1) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Date 1 is required');
    tags.trigger('error');
} else {
    try {
        var date1 = new Date(d1);
        if (isNaN(date1.getTime())) throw new Error('Invalid Date 1');

        if (op === 'difference') {
            if (!d2) throw new Error('Date 2 required for difference');
            var date2 = new Date(d2);
            if (isNaN(date2.getTime())) throw new Error('Invalid Date 2');

            var ms = date2.getTime() - date1.getTime();
            var absMs = Math.abs(ms);
            var totalSecs = Math.floor(absMs / 1000);
            var totalMins = Math.floor(totalSecs / 60);
            var totalHrs = Math.floor(totalMins / 60);
            var totalDays = Math.floor(totalHrs / 24);

            output.set('Result', totalDays + ' days');
            output.set('TotalMilliseconds', ms);
            output.set('TotalSeconds', ms >= 0 ? totalSecs : -totalSecs);
            output.set('TotalMinutes', ms >= 0 ? totalMins : -totalMins);
            output.set('TotalHours', ms >= 0 ? totalHrs : -totalHrs);
            output.set('TotalDays', ms >= 0 ? totalDays : -totalDays);
            output.set('IsFuture', ms > 0);
            output.set('IsPast', ms < 0);
            log.info('Difference: ' + totalDays + ' days');
        } else {
            var r = new Date(date1.getTime());
            var mult = op === 'subtract' ? -1 : 1;

            if (yrs) r.setFullYear(r.getFullYear() + yrs * mult);
            if (mos) r.setMonth(r.getMonth() + mos * mult);
            if (wks) r.setDate(r.getDate() + wks * 7 * mult);
            if (dys) r.setDate(r.getDate() + dys * mult);
            if (hrs) r.setHours(r.getHours() + hrs * mult);
            if (mins) r.setMinutes(r.getMinutes() + mins * mult);
            if (secs) r.setSeconds(r.getSeconds() + secs * mult);

            output.set('Result', r.toISOString());
            output.set('ResultDate', r.toISOString().split('T')[0]);
            output.set('Unix', Math.floor(r.getTime() / 1000));
            output.set('Year', r.getFullYear());
            output.set('Month', r.getMonth() + 1);
            output.set('Day', r.getDate());
            log.info('Result: ' + r.toISOString());
        }

        output.set('HasErrors', false);
        output.set('ErrorMessage', '');
        tags.trigger('success');
    } catch (ex) {
        log.error('Error: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        tags.trigger('error');
    }
}
